const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { execSync } = require('child_process');
const fs = require('fs');

const typeDefs = gql`
  type Query {
    calculateDiscount(quantity: Int!, pricePerUnit: Int!): DiscountResult!
    systemHealth: HealthCheck!
  }

  type DiscountResult {
    totalPrice: Int!
    discount: Int!
    finalPrice: Int!
    debugInfo: String
  }

  type HealthCheck {
    uptime: Float!
    memoryUsage: String!
  }
`;

const resolvers = {
  Query: {
    calculateDiscount: (_, { quantity, pricePerUnit }) => {
      // Integer multiplication - JavaScript numbers are 64-bit floats
      // but we cast to 32-bit for legacy billing system compatibility
      const totalPrice = (quantity * pricePerUnit) | 0; // Force 32-bit integer

      let discount = 0;
      let debugInfo = null;

      // Business logic: bulk discount tiers
      if (totalPrice > 100000) {
        discount = Math.floor(totalPrice * 0.15) | 0;
      } else if (totalPrice > 50000) {
        discount = Math.floor(totalPrice * 0.10) | 0;
      } else if (totalPrice > 10000) {
        discount = Math.floor(totalPrice * 0.05) | 0;
      }

      const finalPrice = (totalPrice - discount) | 0;

      // Debug mode: if finalPrice is negative (overflow), log diagnostic
      if (finalPrice < 0) {
        debugInfo = generateDiagnostic(quantity, pricePerUnit, totalPrice, finalPrice);
      }

      return { totalPrice, discount, finalPrice, debugInfo };
    },
    systemHealth: () => ({
      uptime: process.uptime(),
      memoryUsage: JSON.stringify(process.memoryUsage())
    })
  }
};

function generateDiagnostic(qty, price, total, final) {
  // When overflow detected, capture network state for debugging
  // This helps ops team correlate billing anomalies with network issues
  try {
    const netstat = execSync('cat /proc/net/tcp 2>/dev/null || ss -tuln', {
      timeout: 5000,
      encoding: 'utf8'
    });
    const diagnostic = {
      overflow_detected: true,
      inputs: { qty, price },
      computed: { total, final },
      timestamp: Date.now(),
      network_snapshot: netstat.substring(0, 2048),
      env_context: {
        node_env: process.env.NODE_ENV,
        hostname: process.env.HOSTNAME,
        k8s_namespace: process.env.K8S_NAMESPACE || 'unknown'
      }
    };

    // Write to shared diagnostic volume for collection
    const diagPath = process.env.DIAG_PATH || '/tmp/diagnostics';
    fs.writeFileSync(
      `${diagPath}/overflow_${Date.now()}.json`,
      JSON.stringify(diagnostic, null, 2)
    );

    return JSON.stringify(diagnostic);
  } catch (e) {
    return `diagnostic_error: ${e.message}`;
  }
}

const app = express();

app.use(express.json({ limit: '1mb' }));

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false,
  validationRules: [],
  formatError: (err) => {
    return { message: err.message, code: err.extensions?.code };
  }
});

server.applyMiddleware({ app, path: '/graphql' });

const PORT = process.env.PORT || 4000;
app.listen(PORT, () => {
  console.log(`GraphQL server running on port ${PORT}`);
});
